// Shared calculation rules for manual token records. Not a wallet balance or tax ledger.
export function cleanHolding(b={}){const text=(v,n)=>typeof v==='string'?v.trim().slice(0,n):'';const amount=Number(b.amount),cost=Number(b.cost||0),price=b.manualPrice===''||b.manualPrice==null?null:Number(b.manualPrice);if(!text(b.symbol,20)||!Number.isFinite(amount)||amount<=0||amount>1e15||!Number.isFinite(cost)||cost<0||cost>1e12||(price!==null&&(!Number.isFinite(price)||price<0||price>1e12)))throw Error('INVALID_HOLDING');let date=text(b.receivedAt,10);if(date&&(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date))throw Error('INVALID_RECEIVED_DATE');return {symbol:text(b.symbol,20),chain:text(b.chain,40),contract:text(b.contract,100),amount,cost,price,priceId:/^[a-z0-9-]{1,80}$/.test(b.priceId||'')?b.priceId:'',claimStatus:['pending','eligible','claimed','vesting'].includes(b.claimStatus)?b.claimStatus:'pending',receivedAt:date}}
export function portfolioSummary(rows,prices={}){let value=0,cost=0,unknown=0,claimed=0,waiting=0,vesting=0;for(const row of rows){if(row.archived)continue;if(row.claim_status==='vesting'){vesting++;continue}if(row.claim_status!=='claimed'){waiting++;continue}claimed++;cost+=Number(row.cost)||0;const fetched=prices[row.price_id]?.usd,price=typeof fetched==='number'&&Number.isFinite(fetched)&&fetched>=0?fetched:row.manual_price;if(price===null||price===undefined||!Number.isFinite(Number(price))){unknown++;continue}value+=Number(row.amount)*Number(price)}return {value,cost,unknown,claimed,waiting,vesting,net:unknown?null:value-cost}}
export function holdingsCSV(rows){const cell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s)&&typeof v!=='number')s="'"+s;return '"'+s.replaceAll('"','""')+'"'};return [['symbol','chain','amount','cost_usd','manual_price_usd','price_id','claim_status','received_at','archived','revision'],...rows.map(r=>[r.symbol,r.chain,r.amount,r.cost,r.manual_price,r.price_id,r.claim_status,r.received_at,r.archived,r.revision])].map(row=>row.map(cell).join(',')).join('\r\n')}

export const GUEST_HOLDINGS_KEY='museum-guest-holdings-v1';
export function guestHoldingsRequest(storage,path,body,method='GET',now=new Date(),makeId=()=>globalThis.crypto?.randomUUID?.()||'local-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)){
 let raw;try{raw=JSON.parse(storage.getItem(GUEST_HOLDINGS_KEY)||'[]')}catch{raw=[]}const rows=(Array.isArray(raw)?raw:[]).slice(0,100).flatMap(r=>{try{if(!/^[a-zA-Z0-9-]{1,80}$/.test(r.id||''))return [];const h=cleanHolding({symbol:r.symbol,chain:r.chain,contract:r.contract,amount:r.amount,cost:r.cost,manualPrice:r.manual_price,priceId:r.price_id,claimStatus:r.claim_status,receivedAt:r.received_at});return [{id:r.id,symbol:h.symbol,chain:h.chain,contract:h.contract,amount:h.amount,cost:h.cost,manual_price:h.price,price_id:h.priceId,claim_status:h.claimStatus,received_at:h.receivedAt,revision:Number.isSafeInteger(r.revision)&&r.revision>0?r.revision:1,archived:r.archived===1?1:0,created_at:typeof r.created_at==='string'?r.created_at:now.toISOString(),updated_at:typeof r.updated_at==='string'?r.updated_at:''}]}catch{return []}});
 if(method==='GET')return {holdings:rows,storage:'device'};
 let record;if(path==='/holdings/archive'){record=rows.find(r=>r.id===body.id);if(!record||record.revision!==body.revision)throw Error('HOLDING_CHANGED_OR_NOT_FOUND');if(typeof body.archived!=='boolean')throw Error('INVALID_ARCHIVE');record.archived=body.archived?1:0;record.revision++;record.updated_at=now.toISOString()}else{const h=cleanHolding(body);if(method==='PUT'){record=rows.find(r=>r.id===body.id);if(!record||record.revision!==body.revision)throw Error('HOLDING_CHANGED_OR_NOT_FOUND')}else{if(rows.length>=100)throw Error('HOLDINGS_LIMIT');record={id:makeId(),revision:0,archived:0,created_at:now.toISOString()};rows.unshift(record)}Object.assign(record,{symbol:h.symbol,chain:h.chain,contract:h.contract,amount:h.amount,cost:h.cost,manual_price:h.price,price_id:h.priceId,claim_status:h.claimStatus,received_at:h.receivedAt,revision:record.revision+1,updated_at:now.toISOString()})}storage.setItem(GUEST_HOLDINGS_KEY,JSON.stringify(rows));return {saved:true,storage:'device',revision:record.revision}
}
